result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "stacklang.mjs", "content": "// stacklang.mjs — a tiny concatenative stack language.
//
// Tokens are whitespace-separated. Number literals push themselves.
// Words:
//   + - * /   arithmetic (a b -- a+b etc.)
//   <         comparison, pushes 1 or 0
//   dup       ( x -- x x )
//   swap      ( x y -- y x )
//   drop      ( x -- )
//   [ ... ]   push a quotation (unevaluated token list, nestable)
//   call      ( quot -- ) runs a quotation
//   ifelse    ( else-quot then-quot cond -- ) cond 0 is false

export class StackLangError extends Error {
  constructor(message) {
    super(message);
    this.name = 'StackLangError';
  }
}

const isNumber = (tok) =>
  tok !== '' && !Number.isNaN(Number(tok));

/** Parse flat tokens into a tree; quotations become arrays. */
function parse(tokens) {
  let i = 0;

  function parseSeq(terminator, depth) {
    const out = [];
    while (i < tokens.length) {
      const tok = tokens[i++];
      if (tok === ']') {
        if (terminator === null)
          throw new StackLangError(`unmatched ']' at token ${i}`);
        return out;
      }
      if (tok === '[') {
        out.push(parseSeq(']', depth + 1));
      } else {
        out.push(isNumber(tok) ? Number(tok) : tok);
      }
    }
    if (terminator !== null)
      throw new StackLangError("unmatched '[': expected ']' before end of input");
    return out;
  }

  return parseSeq(null, 0);
}

/** Execute a parsed program against a stack. */
function evalProgram(program, stack) {
  for (const item of program) {
    if (typeof item === 'number') {
      stack.push(item);
      continue;
    }
    if (Array.isArray(item)) {
      stack.push(item);
      continue;
    }

    const need = (n, what = 'operands') => {
      if (stack.length < n)
        throw new StackLangError(
          `stack underflow: '${item}' needs ${n} ${what}, stack has ${stack.length}`
        );
    };
    const pop = () => {
      need(1, 'values');
      return stack.pop();
    };
    const popQuot = (role) => {
      const q = pop();
      if (!Array.isArray(q))
        throw new StackLangError(
          `'${item}' expected a ${role} quotation, got ${typeof q === 'number' ? q : `'${q}'`}`
        );
      return q;
    };

    switch (item) {
      case '+':
      case '-':
      case '*':
      case '/': {
        need(2);
        const b = stack.pop();
        const a = stack.pop();
        stack.push(a === undefined || b === undefined ? NaN
          : item === '+' ? a + b
          : item === '-' ? a - b
          : item === '*' ? a * b
          : a / b);
        break;
      }
      case '<': {
        need(2);
        const b = stack.pop();
        const a = stack.pop();
        stack.push(a < b ? 1 : 0);
        break;
      }
      case 'dup': {
        need(1);
        stack.push(stack[stack.length - 1]);
        break;
      }
      case 'swap': {
        need(2);
        [stack[stack.length - 2], stack[stack.length - 1]] =
          [stack[stack.length - 1], stack[stack.length - 2]];
        break;
      }
      case 'drop': {
        pop();
        break;
      }
      case 'call': {
        const quot = popQuot('callable');
        evalProgram(quot, stack);
        break;
      }
      case 'ifelse': {
        need(3, 'quotations/condition');
        const elseQ = popQuot("'ifelse' else branch");
        const thenQ = popQuot("'ifelse' then branch");
        const cond = pop();
        evalProgram(cond !== 0 ? thenQ : elseQ, stack);
        break;
      }
      default:
        throw new StackLangError(`unknown word: '${item}'`);
    }
  }
}

/** Run source text, returning the final stack as an array. */
export function run(src) {
  const tokens = String(src).trim().split(/\s+/).filter((t) => t !== '');
  const program = parse(tokens);
  const stack = [];
  evalProgram(program, stack);
  return stack;
}
"})
