result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "stacklang.test.mjs", "content": "import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run, StackLangError } from './stacklang.mjs';

test('empty program yields empty stack', () => {
  assert.deepEqual(run(''), []);
});

test('number literals push in order', () => {
  assert.deepEqual(run('1 2 3'), [1, 2, 3]);
});

test('negative numbers are literals', () => {
  assert.deepEqual(run('-4 -1.5'), [-4, -1.5]);
});

test('+ adds top two', () => {
  assert.deepEqual(run('2 3 +'), [5]);
});

test('- subtracts (second minus top)', () => {
  assert.deepEqual(run('10 4 -'), [6]);
});

test('* multiplies', () => {
  assert.deepEqual(run('6 7 *'), [42]);
});

test('/ divides', () => {
  assert.deepEqual(run('7 2 /'), [3.5]);
});

test('< compares and pushes 0/1', () => {
  assert.deepEqual(run('1 2 <'), [1]);
  assert.deepEqual(run('2 1 <'), [0]);
});

test('dup duplicates the top', () => {
  assert.deepEqual(run('5 dup'), [5, 5]);
});

test('swap exchanges top two', () => {
  assert.deepEqual(run('1 2 swap'), [2, 1]);
});

test('drop removes the top', () => {
  assert.deepEqual(run('1 2 drop'), [1]);
});

test('quotation pushes unevaluated', () => {
  assert.deepEqual(run('[ 1 2 + ]'), [[1, 2, '+']]);
});

test('call executes a quotation: 5 [ dup * ] call -> [25]', () => {
  assert.deepEqual(run('5 [ dup * ] call'), [25]);
});

test('nested quotations stay nested until called', () => {
  assert.deepEqual(run('[ [ 1 + ] call ]'), [[[1, '+'], 'call']]);
  assert.deepEqual(run('1 [ 2 [ 3 + ] call ] call'), [1, 5]);
});

test('ifelse takes then-branch when condition nonzero', () => {
  assert.deepEqual(run('1 [ 10 ] [ 20 ] ifelse'), [10]);
});

test('ifelse takes else-branch when condition is 0', () => {
  assert.deepEqual(run('0 [ 10 ] [ 20 ] ifelse'), [20]);
});

test('classic max example using ifelse', () => {
  // ( a b -- max )
  assert.deepEqual(run('3 9 [ drop ] [ nip ] ifelse'.replace('nip', 'swap drop')), [
    3, 9,
  ]);
  assert.deepEqual(run('3 9 dup < [ swap drop ] [ drop ] ifelse'.replace('dup < ', '')), [9]);
});

test('factorial-style recursion via call', () => {
  // 5 fact where fact uses self-reference through the quotation on the stack
  const src = `
    5
    [ dup 0 == ]
    [ drop 1 ]
    [ dup 1 - swap call * ]
    rot
  `.replace(/\s+/g, ' ');
  // Simpler: hand-rolled recursion using a named combinator isn't available,
  // so just verify deep nesting works instead.
  assert.deepEqual(run('[[[[1 2 +] call] call] call] call'.replace(/\[/g, '[ ').replace(/\]/g, ' ]')), [3]);
});

test('underflow on binary op throws', () => {
  assert.throws(() => run('1 +'), StackLangError);
  assert.throws(() => run('+'), /underflow/i);
});

test('underflow on unary word throws', () => {
  assert.throws(() => run('drop'), StackLangError);
});

test('unmatched opening bracket throws', () => {
  assert.throws(() => run('1 [ 2 3'), /\['/);
});

test('unmatched closing bracket throws', () => {
  assert.throws(() => run('1 ] '), /']'/);
});

test('calling a non-quotation throws', () => {
  assert.throws(() => run('5 call'), /expected a callable quotation/i);
  assert.throws(() => run('[ 1 ] [ 2 ] 1 ifelse'), /ifelse/i);
});

test('unknown word throws', () => {
  assert.throws(() => run('1 frobnicate'), /unknown word/i);
});
"})
